"""Isolated historical JSON helper only; no provider/client/credentials."""
import json
def parse_first_json(text):
    """Return the first complete JSON object in a model's reply.
    Models sometimes wrap it in code fences, add words, or send two objects; take the first one."""
    decoder = json.JSONDecoder()
    start = text.find("{")
    while start != -1:
        try:
            obj, _ = decoder.raw_decode(text, start)
            if isinstance(obj, dict):
                return obj
        except json.JSONDecodeError:
            pass
        start = text.find("{", start + 1)
    raise ValueError(f"model reply contained no JSON object: {text[:200]!r}")
